/**
 * Report how this installation signs people in
 *
 * Single-user mode accepts the installation token and the loopback browser session. Team mode (ADR 0046) signs members in through the configured OIDC issuer; the installation token is then break-glass administration only.
 */
export const getAuthenticationMode = <ThrowOnError extends boolean = false>(options?: Options<GetAuthenticationModeData, ThrowOnError>): RequestResult<GetAuthenticationModeResponses, GetAuthenticationModeErrors, ThrowOnError> => (options?.client ?? client).get<GetAuthenticationModeResponses, GetAuthenticationModeErrors, ThrowOnError>({ url: '/auth/mode', ...options });

/**
 * Redirect the browser to the OIDC issuer to sign in
 *
 * Starts an authorization code sign-in with PKCE. State, nonce, and the PKCE verifier stay in daemon memory and are single-use. Before the installation is claimed, this sign-in can only claim it.
 */
export const startOidcSignIn = <ThrowOnError extends boolean = false>(options?: Options<StartOidcSignInData, ThrowOnError>): RequestResult<StartOidcSignInResponses, StartOidcSignInErrors, ThrowOnError> => (options?.client ?? client).get<StartOidcSignInResponses, StartOidcSignInErrors, ThrowOnError>({ url: '/auth/oidc/start', ...options });

/**
 * OIDC redirect target; completes a sign-in
 *
 * Authorized by the single-use state. In team mode it sets an HttpOnly SameSite=Strict session cookie. Before the claim it sets a short-lived claim cookie instead. It answers with a redirect to the web UI, or an HTML page that names no account.
 */
export const completeOidcSignIn = <ThrowOnError extends boolean = false>(options?: Options<CompleteOidcSignInData, ThrowOnError>): RequestResult<CompleteOidcSignInResponses, CompleteOidcSignInErrors, ThrowOnError> => (options?.client ?? client).get<CompleteOidcSignInResponses, CompleteOidcSignInErrors, ThrowOnError>({ url: '/auth/oidc/callback', ...options });

/**
 * Claim the installation for the signed-in OIDC identity and turn on team mode
 *
 * Needs both the installation token in the Authorization header and the claim cookie from an OIDC sign-in in the same browser. Binds that identity to the bootstrap owner, turns on team mode, and signs the browser in. It can happen once.
 */
export const claimInstallation = <ThrowOnError extends boolean = false>(options?: Options<ClaimInstallationData, ThrowOnError>): RequestResult<ClaimInstallationResponses, ClaimInstallationErrors, ThrowOnError> => (options?.client ?? client).post<ClaimInstallationResponses, ClaimInstallationErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/auth/claim',
    ...options
});

